`timescale 1ns/1ps

module PATTERN (
    output reg         clk,
    output reg  [95:0] Inst_seq_I,
    output reg  [47:0] Inst_latency_I,
    input  wire [23:0] Inst_order_O,
    input  wire [8:0]  Ex_cycle
);

// ------------------------------------------------------------
// OISS pattern checker
//
// input.txt format:
//   line 1: PATTERN_NUM
//   for every pattern:
//     8 hexadecimal 12-bit instructions
//     8 decimal opcode latencies in this order:
//       ADD SUB MUL DIV LOAD STORE BRANCH JUMP
//
// output.txt format:
//   one decimal golden minimum cycle per pattern
// ------------------------------------------------------------

parameter CYCLE_TIME = 50.0;

integer input_file;
integer output_file;
integer scan_result;
integer pattern_num;
integer pattern_idx;
integer i;
integer j;
integer k;
integer current_inst;
integer previous_inst;
integer issue_ready;
integer dependency_ready;
integer candidate_cycle;
integer opcode_value;
integer rs_value;
integer rt_value;
integer rd_value;

reg [11:0] instruction [0:7];
integer opcode_latency [0:7];
reg [8:0] golden_min_cycle;

integer output_order [0:7];
integer position [0:7];
integer start_cycle [0:7];
integer finish_cycle [0:7];

reg [7:0] read_mask [0:7];
reg [7:0] write_mask [0:7];
reg [7:0] predecessor_mask [0:7];
reg [7:0] seen_mask;

reg [15:0] golden_reg [0:7];
reg [15:0] candidate_reg [0:7];
reg [15:0] golden_dm [0:63];
reg [15:0] candidate_dm [0:63];
reg [15:0] golden_pc;
reg [15:0] candidate_pc;

