// ------------------------------------------------------------
// Decode register read/write sets.
// LOAD/STORE use {rs,rt} as a 6-bit immediate memory address.
// ------------------------------------------------------------
task build_dependency_graph;
    integer a;
    integer b;
    integer op;
    integer rs;
    integer rt;
    integer rd;
    reg [7:0] reads;
    reg [7:0] writes;
    begin
        for (a = 0; a < 8; a = a + 1) begin
            read_mask[a] = 8'b0;
            write_mask[a] = 8'b0;
            predecessor_mask[a] = 8'b0;

            op = instruction[a][11:9];
            rs = instruction[a][8:6];
            rt = instruction[a][5:3];
            rd = instruction[a][2:0];
            reads = 8'b0;
            writes = 8'b0;

            case (op)
                0, 1, 2, 3: begin
                    reads[rs] = 1'b1;
                    reads[rt] = 1'b1;
                    writes[rd] = 1'b1;
                end
                4: begin
                    // LOAD: REG[rd] = DM[{rs,rt}]
                    writes[rd] = 1'b1;
                end
                5: begin
                    // STORE: DM[{rs,rt}] = REG[rd]
                    reads[rd] = 1'b1;
                end
                6: begin
                    // BRANCH reads rs and rt; rd is a signed offset.
                    reads[rs] = 1'b1;
                    reads[rt] = 1'b1;
                end
                7: begin
                    // JUMP uses a signed 9-bit immediate and no registers.
                end
            endcase

            read_mask[a] = reads;
            write_mask[a] = writes;
        end

        // Original program order is preserved for RAW, WAR, and WAW.
        for (a = 0; a < 8; a = a + 1) begin
            for (b = a + 1; b < 8; b = b + 1) begin
                if (((write_mask[a] & read_mask[b]) != 8'b0) ||
                    ((read_mask[a] & write_mask[b]) != 8'b0) ||
                    ((write_mask[a] & write_mask[b]) != 8'b0)) begin
                    predecessor_mask[b][a] = 1'b1;
                end
            end
        end
    end
endtask

// ------------------------------------------------------------
// Initialize two identical pseudo CPUs.
// Initial architectural values are deterministic and reproducible.
// ------------------------------------------------------------
task initialize_pseudo_cpus;
    integer r;
    integer m;
    begin
        for (r = 0; r < 8; r = r + 1) begin
            golden_reg[r] = ((pattern_idx + 1) * 16'h1F3D) +
                            (r * 16'h1357) + 16'h2468;
            candidate_reg[r] = golden_reg[r];
        end

        for (m = 0; m < 64; m = m + 1) begin
            golden_dm[m] = ((pattern_idx + 1) * 16'h00D3) +
                           (m * 16'h0101) + 16'h55AA;
            candidate_dm[m] = golden_dm[m];
        end

        golden_pc = 16'h1000 + pattern_idx;
        candidate_pc = golden_pc;
    end
endtask

// ------------------------------------------------------------
// Execute one instruction on either pseudo CPU.
// cpu_select = 0: golden CPU
// cpu_select = 1: candidate CPU
//
// PC behavior:
//   normal instruction: PC = PC + 1
//   BRANCH: PC = PC + 1 (+ signed rd when taken)
//   JUMP:   PC = PC + signed {rs,rt,rd}
// ------------------------------------------------------------
task execute_instruction;
    input integer cpu_select;
    input integer inst_idx;
    integer op;
    integer rs;
    integer rt;
    integer rd;
    integer address;
    integer signed_offset;
    reg [31:0] multiply_value;
    begin
        op = instruction[inst_idx][11:9];
        rs = instruction[inst_idx][8:6];
        rt = instruction[inst_idx][5:3];
        rd = instruction[inst_idx][2:0];
        address = instruction[inst_idx][8:3];
        signed_offset = 0;
        multiply_value = 32'b0;

        if (cpu_select == 0) begin
            case (op)
                0: begin
                    golden_reg[rd] = golden_reg[rs] + golden_reg[rt];
                    golden_pc = golden_pc + 1;
                end
                1: begin
                    golden_reg[rd] = golden_reg[rs] - golden_reg[rt];
                    golden_pc = golden_pc + 1;
                end
                2: begin
                    multiply_value = golden_reg[rs] * golden_reg[rt];
                    golden_reg[rd] = multiply_value[15:0];
                    golden_pc = golden_pc + 1;
                end
                3: begin
                    if (golden_reg[rt] == 16'b0)
                        golden_reg[rd] = 16'b0;
                    else
                        golden_reg[rd] = golden_reg[rs] / golden_reg[rt];
                    golden_pc = golden_pc + 1;
                end
                4: begin
                    golden_reg[rd] = golden_dm[address];
                    golden_pc = golden_pc + 1;
                end
                5: begin
                    golden_dm[address] = golden_reg[rd];
                    golden_pc = golden_pc + 1;
                end
                6: begin
                    signed_offset = rd;
                    if (instruction[inst_idx][2])
                        signed_offset = signed_offset - 8;

                    if (golden_reg[rs] == golden_reg[rt])
                        golden_pc = golden_pc + 1 + signed_offset;
                    else
                        golden_pc = golden_pc + 1;
                end
                7: begin
                    signed_offset = instruction[inst_idx][8:0];
                    if (instruction[inst_idx][8])
                        signed_offset = signed_offset - 512;
                    golden_pc = golden_pc + signed_offset;
                end
            endcase
        end
        else begin
            case (op)
                0: begin
                    candidate_reg[rd] = candidate_reg[rs] + candidate_reg[rt];
                    candidate_pc = candidate_pc + 1;
                end
                1: begin
                    candidate_reg[rd] = candidate_reg[rs] - candidate_reg[rt];
                    candidate_pc = candidate_pc + 1;
                end
                2: begin
                    multiply_value = candidate_reg[rs] * candidate_reg[rt];
                    candidate_reg[rd] = multiply_value[15:0];
                    candidate_pc = candidate_pc + 1;
                end
                3: begin
                    if (candidate_reg[rt] == 16'b0)
                        candidate_reg[rd] = 16'b0;
                    else
                        candidate_reg[rd] = candidate_reg[rs] / candidate_reg[rt];
                    candidate_pc = candidate_pc + 1;
                end
                4: begin
                    candidate_reg[rd] = candidate_dm[address];
                    candidate_pc = candidate_pc + 1;
                end
                5: begin
                    candidate_dm[address] = candidate_reg[rd];
                    candidate_pc = candidate_pc + 1;
                end
                6: begin
                    signed_offset = rd;
                    if (instruction[inst_idx][2])
                        signed_offset = signed_offset - 8;

                    if (candidate_reg[rs] == candidate_reg[rt])
                        candidate_pc = candidate_pc + 1 + signed_offset;
                    else
                        candidate_pc = candidate_pc + 1;
                end
                7: begin
                    signed_offset = instruction[inst_idx][8:0];
                    if (instruction[inst_idx][8])
                        signed_offset = signed_offset - 512;
                    candidate_pc = candidate_pc + signed_offset;
                end
            endcase
        end
    end
endtask

// ------------------------------------------------------------
// Apply the currently loaded pattern to the combinational DUT.
// Inputs change only at the negative edge of the testbench clock.
// ------------------------------------------------------------
task drive_current_pattern;
    begin
        for (i = 0; i < 8; i = i + 1)
            Inst_seq_I[i*12 +: 12] = instruction[i];

        for (i = 0; i < 8; i = i + 1)
            Inst_latency_I[i*6 +: 6] = opcode_latency[i];
    end
endtask

// ------------------------------------------------------------
// Check the DUT response for the currently applied pattern.
// The input has been stable for one complete clock cycle.
// ------------------------------------------------------------
task check_current_pattern;
    begin
        // Detect X/Z before using output fields as array indices.
        if ((^Ex_cycle === 1'bx) || (^Inst_order_O === 1'bx))
            fail_pattern("DUT output contains X or Z");

        // Check the minimum cycle first, as required by the lab policy.
        if (Ex_cycle !== golden_min_cycle)
            fail_pattern("Ex_cycle does not match the golden minimum cycle");

        // Decode order and verify that it is a complete permutation of 0..7.
        seen_mask = 8'b0;
        for (k = 0; k < 8; k = k + 1) begin
            output_order[k] = Inst_order_O[k*3 +: 3];
            if (seen_mask[output_order[k]] == 1'b1)
                fail_pattern("Inst_order_O contains a repeated instruction index");
            seen_mask[output_order[k]] = 1'b1;
            position[output_order[k]] = k;
        end

        if (seen_mask != 8'hFF)
            fail_pattern("Inst_order_O is not a complete permutation of 0..7");

        // Check RAW/WAR/WAW program-order constraints.
        for (j = 0; j < 8; j = j + 1) begin
            for (i = 0; i < 8; i = i + 1) begin
                if (predecessor_mask[j][i] && (position[i] >= position[j]))
                    fail_pattern("Inst_order_O violates a RAW/WAR/WAW dependency");
            end
        end

        // Recalculate the cycle count from the DUT order.
        for (i = 0; i < 8; i = i + 1) begin
            start_cycle[i] = 0;
            finish_cycle[i] = 0;
        end
        candidate_cycle = 0;

        for (k = 0; k < 8; k = k + 1) begin
            current_inst = output_order[k];

            if (k == 0)
                issue_ready = 0;
            else begin
                previous_inst = output_order[k-1];
                issue_ready = start_cycle[previous_inst] + 1;
            end

            dependency_ready = 0;
            for (i = 0; i < 8; i = i + 1) begin
                if (predecessor_mask[current_inst][i] &&
                    (finish_cycle[i] > dependency_ready)) begin
                    dependency_ready = finish_cycle[i];
                end
            end

            if (issue_ready > dependency_ready)
                start_cycle[current_inst] = issue_ready;
            else
                start_cycle[current_inst] = dependency_ready;

            opcode_value = instruction[current_inst][11:9];
            finish_cycle[current_inst] = start_cycle[current_inst] +
                                         opcode_latency[opcode_value];

            if (finish_cycle[current_inst] > candidate_cycle)
                candidate_cycle = finish_cycle[current_inst];
        end

        if (candidate_cycle != Ex_cycle)
            fail_pattern("The submitted order cannot achieve the submitted Ex_cycle");

        // Functional equivalence check using two pseudo CPUs.
        initialize_pseudo_cpus;

        for (i = 0; i < 8; i = i + 1)
            execute_instruction(0, i);

        for (k = 0; k < 8; k = k + 1)
            execute_instruction(1, output_order[k]);

        for (i = 0; i < 8; i = i + 1) begin
            if (golden_reg[i] !== candidate_reg[i])
                fail_pattern("Pseudo CPU register values do not match");
        end

        for (i = 0; i < 64; i = i + 1) begin
            if (golden_dm[i] !== candidate_dm[i])
                fail_pattern("Pseudo CPU data memory values do not match");
        end

        if (golden_pc !== candidate_pc)
            fail_pattern("Pseudo CPU PC values do not match");

        $display("Pattern %0d passed: minimum cycle = %0d, order = %0d %0d %0d %0d %0d %0d %0d %0d",
                 pattern_idx,
                 Ex_cycle,
                 output_order[0], output_order[1], output_order[2], output_order[3],
                 output_order[4], output_order[5], output_order[6], output_order[7]);
    end
endtask

// ------------------------------------------------------------
// Testbench-only clock generation.
// clk is intentionally NOT connected to the combinational OISS design.
// ------------------------------------------------------------
always #(CYCLE_TIME / 2.0) clk = ~clk;

// ------------------------------------------------------------
// Main pattern flow
//
// At one negative edge, PATTERN.v applies a test pattern.
// At the next negative edge, it checks the corresponding DUT output.
// Therefore, every input remains stable for one complete clock cycle.
// ------------------------------------------------------------
initial begin
    clk = 1'b0;
    Inst_seq_I = 96'b0;
    Inst_latency_I = 48'b0;

    input_file = $fopen("../00_TESTBED/input.txt", "r");
    if (input_file == 0) begin
        $display("Cannot open input.txt");
        $finish;
    end

    output_file = $fopen("../00_TESTBED/output.txt", "r");
    if (output_file == 0) begin
        $display("Cannot open output.txt");
        $finish;
    end

    scan_result = $fscanf(input_file, "%d", pattern_num);
    if (scan_result != 1)
        fail_pattern("Cannot read PATTERN_NUM from input.txt");

    for (pattern_idx = 0; pattern_idx < pattern_num; pattern_idx = pattern_idx + 1) begin
        // Read eight instructions into PATTERN.v's local storage.
        for (i = 0; i < 8; i = i + 1) begin
            scan_result = $fscanf(input_file, "%h", instruction[i]);
            if (scan_result != 1)
                fail_pattern("Cannot read an instruction from input.txt");
        end

        // Read one shared latency per opcode.
        for (i = 0; i < 8; i = i + 1) begin
            scan_result = $fscanf(input_file, "%d", opcode_latency[i]);
            if (scan_result != 1)
                fail_pattern("Cannot read opcode latency from input.txt");
        end

        scan_result = $fscanf(output_file, "%d", golden_min_cycle);
        if (scan_result != 1)
            fail_pattern("Cannot read golden minimum cycle from output.txt");

        build_dependency_graph;

        // Apply this pattern exactly at a negative clock edge.
        @(negedge clk);
        drive_current_pattern;

        // Check the answer at the following negative clock edge.
        @(negedge clk);
        check_current_pattern;
    end

    $display("");
    $display("============================================================");
    $display("All %0d OISS patterns passed", pattern_num);
